use snm01_input_validation::parse_employee_id;

#[test]
fn valid_numeric_input_succeeds() {
    let id = parse_employee_id("1042").expect("valid numeric input should parse");
    assert_eq!(id, 1042);
}

#[test]
fn optional_trimmed_valid_input_succeeds() {
    let id = parse_employee_id(" 1042 ").expect("trimmed numeric input should parse");
    assert_eq!(id, 1042);
}

#[test]
fn alphabetic_input_fails_safely_in_secure_version() {
    let result = std::panic::catch_unwind(|| parse_employee_id("abc"));
    assert!(
        result.is_ok(),
        "secure version should not panic on alphabetic input"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should reject alphabetic input instead of silently accepting it"
    );
}

#[test]
fn empty_input_fails_safely_in_secure_version() {
    let result = std::panic::catch_unwind(|| parse_employee_id(""));
    assert!(
        result.is_ok(),
        "secure version should not panic on empty input"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should reject empty input instead of returning a fallback ID"
    );
}

#[test]
fn malformed_mixed_input_fails_safely_in_secure_version() {
    let result = std::panic::catch_unwind(|| parse_employee_id("12x7"));
    assert!(
        result.is_ok(),
        "secure version should not panic on malformed mixed input"
    );
    assert!(
        result.unwrap().is_err(),
        "secure version should reject malformed mixed input instead of returning a fallback ID"
    );
}
